css:
.launchlab-container {
    padding: 24px;
    background: linear-gradient(160deg, #fff1f6 0%, #f3eaff 45%, #e8f4ff 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2a1b4e;
    max-width: 1280px;
    margin: 0 auto;
}

.launchlab-container h1,
.launchlab-container h3,
.launchlab-container h4 {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.launchlab-container .launchlab-header {
    background: linear-gradient(135deg, #7c3aed 0%, #ec4899 60%, #f59e0b 100%);
    color: #ffffff;
    border-radius: 28px;
    padding: 28px 32px;
    margin-bottom: 24px;
    box-shadow: 0 18px 40px rgba(124, 58, 237, 0.28);
    position: relative;
    overflow: hidden;
}

.launchlab-container .launchlab-header::after {
    content: '';
    position: absolute;
    top: -50%;
    right: -10%;
    width: 260px;
    height: 260px;
    border-radius: 50%;
    background: rgba(255,255,255,0.12);
    filter: blur(10px);
}

.launchlab-container .launchlab-header-badge {
    display: inline-block;
    background: rgba(255,255,255,0.2);
    color: #ffffff;
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    padding: 6px 14px;
    border-radius: 999px;
    margin-bottom: 12px;
    backdrop-filter: blur(6px);
}

.launchlab-container .launchlab-header h1 {
    font-size: 1.75rem;
    font-weight: 800;
    margin: 0 0 8px 0;
    line-height: 1.2;
}

.launchlab-container .launchlab-tagline {
    font-size: 1rem;
    margin: 0;
    opacity: 0.94;
    max-width: 720px;
}

.launchlab-container .launchlab-period-counter {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: #ffffff;
    border: 2px solid #ede9fe;
    border-radius: 999px;
    padding: 8px 18px;
    font-weight: 600;
    color: #6d28d9;
    margin-bottom: 20px;
    box-shadow: 0 4px 12px rgba(109, 40, 217, 0.08);
}

.launchlab-container .launchlab-period-counter span {
    font-size: 0.95rem;
}

.launchlab-container .launchlab-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 26px;
}

.launchlab-container .launchlab-status-card {
    background: #ffffff;
    border-radius: 20px;
    padding: 18px 18px;
    box-shadow: 0 6px 18px rgba(44, 27, 78, 0.08);
    position: relative;
    overflow: hidden;
    border-top: 5px solid #7c3aed;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.launchlab-container .launchlab-status-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 24px rgba(44, 27, 78, 0.12);
}

.launchlab-container .launchlab-status-brand        { border-top-color: #7c3aed; }
.launchlab-container .launchlab-status-consistency  { border-top-color: #06b6d4; }
.launchlab-container .launchlab-status-intent       { border-top-color: #ec4899; }
.launchlab-container .launchlab-status-sales        { border-top-color: #10b981; }
.launchlab-container .launchlab-status-stars        { border-top-color: #f59e0b; }

.launchlab-container .launchlab-label {
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #6b7280;
    margin-bottom: 6px;
}

.launchlab-container .launchlab-value {
    font-size: 2rem;
    font-weight: 800;
    color: #2a1b4e;
    line-height: 1;
}

.launchlab-container .launchlab-persona-card {
    background: #ffffff;
    border-radius: 24px;
    padding: 22px 24px;
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.1);
    margin-bottom: 22px;
    border-left: 6px solid #ec4899;
}

.launchlab-container .launchlab-persona-row {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 12px;
}

.launchlab-container .launchlab-persona-avatar {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    background: linear-gradient(135deg, #ec4899, #7c3aed);
    color: #ffffff;
    font-size: 2.2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    box-shadow: 0 8px 16px rgba(236, 72, 153, 0.3);
}

.launchlab-container .launchlab-persona-name {
    font-size: 1.3rem;
    font-weight: 800;
    color: #2a1b4e;
    line-height: 1.2;
}

.launchlab-container .launchlab-persona-tag {
    display: inline-block;
    background: #f3e8ff;
    color: #7c3aed;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    padding: 3px 10px;
    border-radius: 999px;
    margin-top: 4px;
}

.launchlab-container .launchlab-persona-quote {
    font-style: italic;
    color: #6b7280;
    font-size: 0.9rem;
    margin-top: 6px;
    line-height: 1.4;
}

.launchlab-container .launchlab-persona-body {
    color: #374151;
    line-height: 1.55;
    font-size: 0.95rem;
    margin-bottom: 12px;
}

.launchlab-container .launchlab-persona-jtbd {
    background: #fdf2f8;
    border: 1px dashed #ec4899;
    border-radius: 12px;
    padding: 10px 14px;
    font-size: 0.9rem;
    color: #831843;
    margin-bottom: 10px;
}

.launchlab-container .launchlab-jtbd-tag {
    font-weight: 800;
    color: #9d174d;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.1em;
    margin-right: 6px;
}

.launchlab-container .launchlab-product-banner {
    background: linear-gradient(135deg, #ede9fe, #fce7f3);
    border-radius: 12px;
    padding: 10px 14px;
    font-size: 0.95rem;
    color: #4c1d95;
}

.launchlab-container .launchlab-product-banner strong {
    color: #6d28d9;
}

.launchlab-container .launchlab-controls,
.launchlab-container .launchlab-diagnosis-panel {
    background: #ffffff;
    border-radius: 24px;
    padding: 22px 24px;
    box-shadow: 0 8px 24px rgba(44, 27, 78, 0.08);
    margin-bottom: 22px;
}

.launchlab-container .launchlab-controls h3,
.launchlab-container .launchlab-diagnosis-panel h3 {
    font-size: 1.1rem;
    font-weight: 800;
    margin: 0 0 16px 0;
    color: #2a1b4e;
}

.launchlab-container .launchlab-diag-intro {
    font-size: 0.95rem;
    color: #4b5563;
    margin-bottom: 16px;
    line-height: 1.5;
}

.launchlab-container .launchlab-p-card {
    background: #faf5ff;
    border: 2px solid #ede9fe;
    border-radius: 16px;
    padding: 14px 16px;
    margin-bottom: 12px;
    transition: border-color 0.2s ease, background 0.2s ease;
}

.launchlab-container .launchlab-p-card:hover {
    border-color: #a78bfa;
    background: #f5f3ff;
}

.launchlab-container .launchlab-p-product  { border-left: 6px solid #06b6d4; }
.launchlab-container .launchlab-p-price    { border-left: 6px solid #10b981; }
.launchlab-container .launchlab-p-place    { border-left: 6px solid #f59e0b; }
.launchlab-container .launchlab-p-promotion{ border-left: 6px solid #ec4899; }
.launchlab-container .launchlab-p-diag     { border-left: 6px solid #7c3aed; }

.launchlab-container .launchlab-p-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 4px;
}

.launchlab-container .launchlab-p-icon {
    font-size: 1.2rem;
}

.launchlab-container .launchlab-p-title {
    font-weight: 800;
    color: #2a1b4e;
    font-size: 1rem;
}

.launchlab-container .launchlab-p-hint {
    color: #6b7280;
    font-size: 0.82rem;
    margin-bottom: 10px;
}

.launchlab-container .launchlab-select {
    width: 100%;
    background: #ffffff;
    color: #2a1b4e;
    border: 2px solid #ddd6fe;
    border-radius: 10px;
    padding: 10px 12px;
    font-size: 0.95rem;
    font-family: inherit;
    font-weight: 500;
    cursor: pointer;
    transition: border-color 0.2s ease;
}

.launchlab-container .launchlab-select:focus {
    outline: none;
    border-color: #7c3aed;
    box-shadow: 0 0 0 3px rgba(124, 58, 237, 0.15);
}

.launchlab-container .launchlab-select option {
    background: #ffffff;
    color: #2a1b4e;
}

.launchlab-container .launchlab-action-row {
    display: flex;
    gap: 12px;
    margin-bottom: 22px;
    flex-wrap: wrap;
}

.launchlab-container .launchlab-btn-launch {
    background: linear-gradient(135deg, #7c3aed 0%, #ec4899 100%);
    color: #ffffff;
    border: none;
    border-radius: 14px;
    padding: 14px 26px;
    font-size: 1rem;
    font-weight: 800;
    letter-spacing: 0.02em;
    cursor: pointer;
    box-shadow: 0 10px 22px rgba(124, 58, 237, 0.3);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    flex: 1;
    min-width: 220px;
}

.launchlab-container .launchlab-btn-launch:hover {
    transform: translateY(-2px);
    box-shadow: 0 14px 28px rgba(124, 58, 237, 0.4);
}

.launchlab-container .launchlab-btn-undo {
    background: #ffffff;
    color: #6d28d9;
    border: 2px solid #ede9fe;
    border-radius: 14px;
    padding: 12px 22px;
    font-weight: 700;
    cursor: pointer;
    transition: background 0.2s ease;
}

.launchlab-container .launchlab-btn-undo:hover {
    background: #f5f3ff;
}

.launchlab-container .launchlab-insight {
    background: #fffbeb;
    border: 2px solid #fde68a;
    border-radius: 16px;
    padding: 14px 18px;
    color: #78350f;
    font-size: 0.95rem;
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 22px;
    line-height: 1.5;
}

.launchlab-container .launchlab-insight-icon {
    font-size: 1.3rem;
    flex-shrink: 0;
}

.launchlab-container .launchlab-history {
    background: #ffffff;
    border-radius: 20px;
    padding: 20px 22px;
    box-shadow: 0 6px 18px rgba(44, 27, 78, 0.06);
    margin-bottom: 22px;
    overflow-x: auto;
}

.launchlab-container .launchlab-history h4 {
    font-size: 1rem;
    font-weight: 800;
    color: #2a1b4e;
    margin: 0 0 12px 0;
}

.launchlab-container .launchlab-history table {
    width: 100%;
    font-size: 0.9rem;
}

.launchlab-container .launchlab-history th {
    background: #f5f3ff;
    color: #6d28d9;
    font-weight: 700;
    font-size: 0.8rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    padding: 8px 10px;
    border: none;
}

.launchlab-container .launchlab-history td {
    padding: 8px 10px;
    border-top: 1px solid #f3f4f6;
    color: #2a1b4e;
}

.launchlab-container .launchlab-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
    gap: 20px;
}

.launchlab-container .launchlab-chart-card {
    background: #ffffff;
    border-radius: 20px;
    padding: 20px 22px;
    box-shadow: 0 6px 18px rgba(44, 27, 78, 0.06);
    height: 340px;
    display: flex;
    flex-direction: column;
}

.launchlab-container .launchlab-chart-card h4 {
    font-size: 1rem;
    font-weight: 800;
    color: #2a1b4e;
    margin: 0 0 12px 0;
    flex-shrink: 0;
}

.launchlab-container .launchlab-chart-card canvas {
    flex: 1;
    min-height: 0;
}

@media (max-width: 768px) {
    .launchlab-container {
        padding: 14px;
    }
    .launchlab-container .launchlab-header {
        padding: 20px;
        border-radius: 20px;
    }
    .launchlab-container .launchlab-header h1 {
        font-size: 1.35rem;
    }
    .launchlab-container .launchlab-value {
        font-size: 1.5rem;
    }
    .launchlab-container .launchlab-persona-avatar {
        width: 56px;
        height: 56px;
        font-size: 1.6rem;
    }
    .launchlab-container .launchlab-btn-launch {
        padding: 12px 18px;
        font-size: 0.95rem;
    }
    .launchlab-container .launchlab-chart-card {
        height: 280px;
    }
}

