        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalBrandFit: 0,
                    totalPurchaseIntent: 0,
                    totalSalesUnits: 0,
                    totalRevenue: 0,
                    totalProfit: 0,
                    totalStars: 0,
                    avgConsistency: 0,
                    brandFitHistory: [],
                    consistencyHistory: [],
                    purchaseIntentHistory: [],
                    salesHistory: [],
                    profitHistory: [],
                    starsHistory: [],
                    launches: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    productTier: 1,
                    priceTier: 1,
                    placeChannel: 1,
                    promotionMix: 1,
                    weakest: 0,
                    reason: 0,
                    dimension: 0
                };
            }
            this._updateBriefing(state);
        }

        _currentRound(state) {
            var period = state && state.currentPeriod ? state.currentPeriod : 1;
            var idx = Math.min(Math.max(period - 1, 0), this.ROUNDS.length - 1);
            return this.ROUNDS[idx];
        }

        _t(key) {
            return (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t(key) : key;
        }

        _personaLabel(round) {
            return round.nameKey ? this._t(round.nameKey) : round.personaName;
        }

        _fillSelect(id, options, chosenIndex) {
            var el = document.getElementById(id);
            if (!el) return;
            el.innerHTML = '';
            for (var i = 0; i < options.length; i++) {
                var opt = document.createElement('option');
                opt.value = i;
                opt.textContent = options[i].labelKey ? this._t(options[i].labelKey) : options[i].label;
                if (i === chosenIndex) opt.selected = true;
                el.appendChild(opt);
            }
        }

        _updateBriefing(state) {
            var round = this._currentRound(state);
            var isPortfolio = round.key === 'portfolio';
            var _dec = state.decisions || {};

            var nameEl = document.getElementById('personaName');
            if (nameEl) nameEl.textContent = this._personaLabel(round);
            var tagEl = document.getElementById('personaTag');
            if (tagEl) tagEl.textContent = this._t(round.tagKey);
            var avatarEl = document.getElementById('personaAvatar');
            if (avatarEl) avatarEl.textContent = round.personaAvatar;
            var quoteEl = document.getElementById('personaQuote');
            if (quoteEl) quoteEl.textContent = '"' + this._t(round.quoteKey) + '"';
            var descEl = document.getElementById('personaDescription');
            if (descEl) descEl.textContent = this._t(round.descKey);
            var jtbdEl = document.getElementById('personaJTBD');
            if (jtbdEl) jtbdEl.textContent = this._t(round.jtbdKey);
            var productEl = document.getElementById('productName');
            if (productEl) productEl.textContent = this._t(round.productKey);

            var fourPs = document.getElementById('fourPsPanel');
            var diag = document.getElementById('diagnosisPanel');

            if (isPortfolio) {
                if (fourPs) fourPs.style.display = 'none';
                if (diag) diag.style.display = 'block';

                var weakestOptions = [];
                for (var i = 0; i < 4; i++) {
                    weakestOptions.push({ label: this._personaLabel(this.ROUNDS[i]) + ' — ' + this._t(this.ROUNDS[i].productKey) });
                }
                this._fillSelect('weakestInput', weakestOptions, _dec.weakest || 0);

                var reasonOptions = [
                    { labelKey: 'reason_opt0' },
                    { labelKey: 'reason_opt1' },
                    { labelKey: 'reason_opt2' },
                    { labelKey: 'reason_opt3' }
                ];
                this._fillSelect('reasonInput', reasonOptions, _dec.reason || 0);

                var dimensionOptions = [
                    { labelKey: 'dim_opt0' },
                    { labelKey: 'dim_opt1' },
                    { labelKey: 'dim_opt2' },
                    { labelKey: 'dim_opt3' }
                ];
                this._fillSelect('dimensionInput', dimensionOptions, _dec.dimension || 0);
            } else {
                if (fourPs) fourPs.style.display = 'block';
                if (diag) diag.style.display = 'none';

                this._fillSelect('productTierInput', round.productOptions, _dec.productTier || 0);
                this._fillSelect('priceTierInput', round.priceOptions, _dec.priceTier || 0);
                this._fillSelect('placeChannelInput', round.placeOptions, _dec.placeChannel || 0);
                this._fillSelect('promotionMixInput', round.promotionOptions, _dec.promotionMix || 0);
            }
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            // Do NOT call _updateBriefing() here: it rebuilds the decision <select>s
            // from the STORED decisions and would overwrite the player's current-round
            // choices before we read them (making every decision a no-op).
            var round = this._currentRound(state);

            if (round.key === 'portfolio') {
                var w = document.getElementById('weakestInput');
                var r = document.getElementById('reasonInput');
                var d = document.getElementById('dimensionInput');
                if (w) decisions.weakest = parseInt(w.value, 10);
                if (r) decisions.reason = parseInt(r.value, 10);
                if (d) decisions.dimension = parseInt(d.value, 10);
                if (isNaN(decisions.weakest) || isNaN(decisions.reason) || isNaN(decisions.dimension)) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('diag_warning'), 'warning'
                    );
                    return false;
                }
                return true;
            }

            var pt = document.getElementById('productTierInput');
            var pr = document.getElementById('priceTierInput');
            var pl = document.getElementById('placeChannelInput');
            var pm = document.getElementById('promotionMixInput');
            if (pt) decisions.productTier = parseInt(pt.value, 10);
            if (pr) decisions.priceTier = parseInt(pr.value, 10);
            if (pl) decisions.placeChannel = parseInt(pl.value, 10);
            if (pm) decisions.promotionMix = parseInt(pm.value, 10);

            if (isNaN(decisions.productTier) || isNaN(decisions.priceTier) ||
                isNaN(decisions.placeChannel) || isNaN(decisions.promotionMix)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var round = this._currentRound(state);
            var d = state.decisions;
            var results;

            if (round.key === 'portfolio') {
                results = this._calculatePortfolioResults(state, round);
            } else {
                results = this._calculateLaunchResults(state, round);
            }

            // Push history for charts
            state.domainState.brandFitHistory.push(results.brandFit || 0);
            state.domainState.consistencyHistory.push(results.consistency || 0);
            state.domainState.purchaseIntentHistory.push(results.purchaseIntent || 0);
            state.domainState.salesHistory.push(results.salesUnits || 0);
            state.domainState.profitHistory.push(results.profit || 0);
            state.domainState.starsHistory.push(results.starsEarned || 0);

            // Persist a normalized 0-100 score (stars out of the 15 max) so the
            // grading/reporting layer can read domainState.performance.overallScore.
            var _sc = this._score(state.domainState.totalStars);
            state.domainState.score = _sc;
            state.domainState.performance = { overallScore: _sc, grade: this._grade(_sc) };
            results.score = _sc;
            results.overallScore = _sc;

            var self = this;
            setTimeout(((__eqilNext) => function() {
                // Pass decisions + domainState so the next round's selects/persona render
                // (the minimal {currentPeriod} object made _updateBriefing throw).
                self._updateBriefing({ currentPeriod: __eqilNext, decisions: state.decisions, domainState: state.domainState });
            })((state.currentPeriod || 0) + 1), 500);

            return results;
        }

        _calculateLaunchResults(state, round) {
            var d = state.decisions;
            var ideal = round.ideal;

            var productDelta   = Math.abs(d.productTier   - ideal.product);
            var priceDelta     = Math.abs(d.priceTier     - ideal.price);
            var placeDelta     = Math.abs(d.placeChannel  - ideal.place);
            var promotionDelta = Math.abs(d.promotionMix  - ideal.promotion);

            var productScore   = Math.max(0, 100 - productDelta   * 28);
            var priceScore     = Math.max(0, 100 - priceDelta     * 32);
            var placeScore     = Math.max(0, 100 - placeDelta     * 26);
            var promotionScore = Math.max(0, 100 - promotionDelta * 26);

            var brandFit = Math.round((productScore + priceScore + placeScore + promotionScore) / 4);

            // Mix consistency = how tightly the 4 choices cluster around the same tier.
            var values = [d.productTier, d.priceTier, d.placeChannel, d.promotionMix];
            var mean = (values[0] + values[1] + values[2] + values[3]) / 4;
            var variance = 0;
            for (var i = 0; i < 4; i++) variance += (values[i] - mean) * (values[i] - mean);
            variance = variance / 4;
            var consistency = Math.max(0, Math.round(100 - variance * 35));

            // Purchase intent is weighted toward price match and product fit
            var purchaseIntent = Math.round(priceScore * 0.45 + productScore * 0.30 + promotionScore * 0.15 + placeScore * 0.10);

            // Message recall and authenticity
            var messageRecall = Math.round(promotionScore * 0.65 + placeScore * 0.35);
            var authenticity  = Math.round((productScore + promotionScore) / 2);

            // Sales forecast and margin
            var demandFactor = (brandFit / 100) * (purchaseIntent / 100);
            var priceIdx = Math.max(0, Math.min(3, d.priceTier));
            var priceTierMix = [1.5, 1.15, 0.85, 0.55][priceIdx];
            var salesUnits = Math.max(round.minDemand, Math.round(round.baseDemand * demandFactor * priceTierMix));

            var unitPrice = round.priceOptions[priceIdx].unitPrice;
            var unitCost  = round.unitCostByTier[Math.max(0, Math.min(3, d.productTier))];
            var revenue = salesUnits * unitPrice;
            var costs   = salesUnits * unitCost;
            var profit  = Math.round(revenue - costs);
            var marginPct = revenue > 0 ? Math.round((profit / revenue) * 100) : 0;

            // Stars — follow the concept star triggers per round
            var stars = 1; // completed the round
            if (round.key === 'priya' && consistency >= 80 && purchaseIntent >= 60) stars = 2;
            if (round.key === 'greens' && consistency >= 70 && marginPct >= 15 && brandFit >= 70) stars = 2;
            if (round.key === 'kai' && brandFit >= 75 && authenticity >= 70) stars = 2;
            if (round.key === 'timeshort' && purchaseIntent >= 55 && marginPct >= 12 && brandFit >= 70) stars = 2;
            if (profit > 0 && consistency >= 80 && brandFit >= 80) stars = 3;

            // Update cumulative domain state
            state.domainState.totalBrandFit += brandFit;
            state.domainState.totalPurchaseIntent += purchaseIntent;
            state.domainState.totalSalesUnits += salesUnits;
            state.domainState.totalRevenue += revenue;
            state.domainState.totalProfit += profit;
            state.domainState.totalStars += stars;
            state.domainState.avgConsistency = Math.round(
                (state.domainState.avgConsistency * state.domainState.launches.length + consistency) /
                (state.domainState.launches.length + 1)
            );

            var launchRecord = {
                key: round.key,
                personaName: this._personaLabel(round),
                productName: this._t(round.productKey),
                brandFit: brandFit,
                consistency: consistency,
                purchaseIntent: purchaseIntent,
                messageRecall: messageRecall,
                salesUnits: salesUnits,
                revenue: revenue,
                profit: profit,
                marginPct: marginPct,
                stars: stars,
                decisions: {
                    product: this._t(round.productOptions[d.productTier].labelKey),
                    price: this._t(round.priceOptions[d.priceTier].labelKey),
                    place: this._t(round.placeOptions[d.placeChannel].labelKey),
                    promotion: this._t(round.promotionOptions[d.promotionMix].labelKey)
                }
            };
            state.domainState.launches.push(launchRecord);

            return {
                period: state.currentPeriod,
                brandFit: brandFit,
                consistency: consistency,
                purchaseIntent: purchaseIntent,
                messageRecall: messageRecall,
                authenticity: authenticity,
                salesUnits: salesUnits,
                revenue: revenue,
                profit: profit,
                marginPct: marginPct,
                starsEarned: stars,
                personaName: this._personaLabel(round),
                productName: this._t(round.productKey),
                weakestCorrect: null,
                reasonCorrect: null,
                dimensionCorrect: null
            };
        }

        _calculatePortfolioResults(state, round) {
            var launches = state.domainState.launches || [];
            // Weakest = lowest profit
            var weakestIdx = 0;
            var weakestProfit = Number.POSITIVE_INFINITY;
            for (var i = 0; i < launches.length; i++) {
                if (launches[i].profit < weakestProfit) {
                    weakestProfit = launches[i].profit;
                    weakestIdx = i;
                }
            }

            // Reason inferred from which delta was biggest in the weakest launch vs ideal
            var worstRound = this.ROUNDS[weakestIdx];
            var launchRec = launches[weakestIdx];
            var reasonIdx = 0; // default mis-positioning
            if (worstRound && worstRound.ideal) {
                var deltas = [
                    0,
                    0,
                    0,
                    0
                ];
                // Rebuild player-chosen tiers from record labels is brittle; instead, rely on stored history record
                var hist = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.history) || [];
                if (hist[weakestIdx] && hist[weakestIdx].decisions) {
                    var hd = hist[weakestIdx].decisions;
                    deltas[0] = Math.abs((hd.productTier || 0) - worstRound.ideal.product);     // positioning
                    deltas[1] = Math.abs((hd.priceTier || 0) - worstRound.ideal.price);         // price
                    deltas[2] = Math.abs((hd.placeChannel || 0) - worstRound.ideal.place);      // channel
                    deltas[3] = Math.abs((hd.promotionMix || 0) - worstRound.ideal.promotion);  // promotion
                    var maxDelta = deltas[0];
                    reasonIdx = 0;
                    for (var j = 1; j < 4; j++) {
                        if (deltas[j] > maxDelta) { maxDelta = deltas[j]; reasonIdx = j; }
                    }
                }
            }

            // Kai is primarily psychographic / generational — coded as psychographic = 2
            var correctDimension = 2;

            var d = state.decisions;
            var weakestCorrect = (d.weakest === weakestIdx);
            var reasonCorrect  = (d.reason === reasonIdx);
            var dimensionCorrect = (d.dimension === correctDimension);

            var diagScore = 0;
            if (weakestCorrect) diagScore += 40;
            if (reasonCorrect)  diagScore += 40;
            if (dimensionCorrect) diagScore += 20;

            var stars = 1;
            if (diagScore >= 80) stars = 2;
            if (diagScore === 100) stars = 3;

            state.domainState.totalStars += stars;

            return {
                period: state.currentPeriod,
                brandFit: diagScore,
                consistency: diagScore,
                purchaseIntent: 0,
                messageRecall: 0,
                authenticity: 0,
                salesUnits: 0,
                revenue: 0,
                profit: 0,
                marginPct: 0,
                starsEarned: stars,
                personaName: this._personaLabel(round),
                productName: this._t(round.productKey),
                diagnosticScore: diagScore,
                weakestCorrect: weakestCorrect,
                reasonCorrect: reasonCorrect,
                dimensionCorrect: dimensionCorrect,
                correctWeakestLabel: this.ROUNDS[weakestIdx] ? this._personaLabel(this.ROUNDS[weakestIdx]) : '',
                correctReasonIndex: reasonIdx
            };
        }

