            var labels = state.domainState.brandFitHistory.map(function(_, i) { return 'Q' + (i + 1); });
            return {
                brandFitChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.brandFitHistory },
                        { data: state.domainState.consistencyHistory }
                    ]
                },
                salesChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.salesHistory }]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.diagnosticScore != null) {
                if (results.diagnosticScore === 100) return window.mySimulation.t('hint_diag_perfect');
                if (results.diagnosticScore < 60) return window.mySimulation.t('hint_diag_weak');
                return window.mySimulation.t('hint_diag_ok');
            }
            if (results.consistency != null && results.consistency < 50) return window.mySimulation.t('hint_inconsistent');
            if (results.purchaseIntent != null && results.purchaseIntent < 40) return window.mySimulation.t('hint_low_intent');
            if (results.profit != null && results.profit < 0) return window.mySimulation.t('hint_loss');
            if (results.brandFit != null && results.brandFit >= 85) return window.mySimulation.t('hint_strong');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.personaName',   label: 'Tribe',         i18nKey: 'col_tribe' },
                { key: 'results.productName',   label: 'Product',       i18nKey: 'col_product' },
                { key: 'results.brandFit',      label: 'Brand Fit',     i18nKey: 'col_brand_fit',  formatter: function(v) { return (v == null ? '—' : v + '/100'); } },
                { key: 'results.consistency',   label: 'Consistency',   i18nKey: 'col_consistency', formatter: function(v) { return (v == null ? '—' : v + '%'); } },
                { key: 'results.purchaseIntent',label: 'Purchase Intent', i18nKey: 'col_intent',   formatter: function(v) { return (v == null ? '—' : v + '%'); } },
                { key: 'results.salesUnits',    label: 'Units',         i18nKey: 'col_units',      formatter: function(v) { return (v == null ? '—' : v.toLocaleString()); } },
                { key: 'results.profit',        label: 'Profit',        i18nKey: 'col_profit',     formatter: function(v) { return (v == null ? '—' : '£' + v.toLocaleString()); } },
                { key: 'results.starsEarned',   label: 'Stars',         i18nKey: 'col_stars',      formatter: function(v) { return (v == null ? '—' : '⭐'.repeat(v)); } }
            ];
        }

        getPresets() { return null; }

        _score(totalStars) {
            return Math.max(0, Math.min(100, Math.round((totalStars / 15) * 100)));
        }

        _grade(score) {
            // Grade label goes through the tier_* translation keys so it renders in the run language.
            if (score >= 80) return this._t('tier_cmo');
            if (score >= 55) return this._t('tier_brand_manager');
            return this._t('tier_marketer');
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalProfit = 0;
            var totalStars = 0;
            var profitableLaunches = 0;
            var consistencyHits = 0;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                totalProfit += (r.profit || 0);
                totalStars  += (r.starsEarned || 0);
                if ((r.profit || 0) > 0) profitableLaunches++;
                if ((r.consistency || 0) >= 70) consistencyHits++;
            }

            var t = function(k) { return window.mySimulation.t(k); };
            // Same thresholds as before; the label is now the translated tier name.
            var performanceKey = 'tier_marketer';
            if (consistencyHits >= 4) performanceKey = 'tier_brand_manager';
            if (consistencyHits === 5 && profitableLaunches >= 4) performanceKey = 'tier_cmo';
            var performance = t(performanceKey);
            var insights = [];
            insights.push(t('sum_total_stars') + ': ' + totalStars);
            insights.push(t('sum_profitable') + ': ' + profitableLaunches + ' ' + t('sum_of') + ' ' + (history.length - 1));
            if (consistencyHits >= 4) {
                insights.push(t('sum_coherent'));
            } else {
                insights.push(t('sum_inconsistent'));
            }

            return {
                totalProfit: totalProfit,
                totalStars: totalStars,
                overallScore: this._score(totalStars),
                totalPeriods: history.length,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = function(k) { return window.mySimulation.t(k); };
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : 0;
            // summary.performance (and the _grade fallback) already carry the translated tier label.
            var perfL = summary.performance || this._grade(score);
            var color = score >= 80 ? '#7c3aed' : (score >= 55 ? '#06b6d4' : '#64748b');
            var stars = (typeof summary.totalStars === 'number') ? summary.totalStars : 0;
            var profit = (typeof summary.totalProfit === 'number') ? summary.totalProfit : 0;
            var starRow = '\u2b50'.repeat(Math.max(0, Math.min(15, stars)));
            var kpis = [
                [t('sum_total_stars'), stars + ' / 15'],
                [t('col_profit'), '\u00a3' + Math.round(profit).toLocaleString()]
            ];
            var kpiRow = kpis.map(function(k) { return '<span style="display:inline-block;margin:4px 10px;"><strong>' + k[1] + '</strong> ' + k[0] + '</span>'; }).join('');
            var ins = summary.insights || [];
            var items = ins.map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var insBlock = items ? ('<ul style="text-align:left;margin:12px auto 0;display:inline-block;">' + items + '</ul>') : '';
            return '<div class="completion-message text-center p-4">' +
                '<h4 style="margin-bottom:8px;">' + t('completion_heading') + '</h4>' +
                '<div style="font-size:2.6rem;font-weight:800;color:' + color + ';">' + score + '/100</div>' +
                '<p class="lead" style="margin:2px 0;">' + t('overall_score_label') + '</p>' +
                '<p style="font-weight:700;color:' + color + ';">' + perfL + '</p>' +
                '<p style="font-size:1.3rem;margin:6px 0;">' + starRow + '</p>' +
                '<p class="text-muted" style="margin:8px 0;">' + kpiRow + '</p>' +
                insBlock +
                '<hr class="my-3"><p class="text-muted">' + t('thanks_msg') + '</p></div>';
        }

